from sqlalchemy import select
from .models import Part

class PartRepository:
    def __init__(self, session):
        self.session = session

    def get_by_sku(self, sku: str) -> Part | None:
        return self.session.scalar(select(Part).where(Part.sku == sku))

    def add(self, part: Part) -> Part:
        self.session.add(part)
        self.session.flush()   # id is nu bekend; de caller beslist over commit
        return part
